cd /tmp/ajv-shape-check && node --input-type=module -e "
import Ajv from 'ajv';
const ajv = new Ajv({strict: false, validateFormats: false, allErrors: true});
const fmt = errors => errors.map(e => (e.instancePath ? \`\${e.instancePath} \${e.message}\` : e.message)).join('; ');
const run = (v, input) => { v(input); return fmt(v.errors ?? []); };
const required = ajv.compile({type:'object', properties:{location:{type:'string'}}, required:['location']});
const typed = ajv.compile({type:'object', properties:{ssn:{type:'string'}}, required:['ssn']});
console.log('missing required :', run(required, {}));
console.log('wrong type       :', run(typed, {ssn: 123456789}));
console.log('extra prop       :', run(ajv.compile({type:'object', properties:{location:{type:'string'}}}), {location:'Berlin', units:'metric'}));
console.log('nested path      :', run(ajv.compile({type:'object', properties:{address:{type:'object', properties:{zip:{type:'string'}}}}}), {address:{zip:5}}));
console.log('enum             :', run(ajv.compile({type:'object', properties:{units:{enum:['celsius','fahrenheit']}}}), {units:'kelvin'}));
console.log('typeof default import:', typeof Ajv);
"

